// The scroll world: its config, the film it points at, and the rules its copy
// follows. The film itself is regenerated by world/render.mjs + world/motion.mjs,
// so these guard the seams between the config, the assets and the page.

import { describe, expect, it } from "vitest";
import { existsSync } from "node:fs";
import { readFile, stat } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { JSDOM } from "jsdom";
import { openExternalActions, sceneStep, world } from "../world.js";

const PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUT = path.join(PROJECT_ROOT, "world", "out");
const read = (file) => readFile(path.join(PROJECT_ROOT, file), "utf8");

const html = await read("world.html"); // built to index.html
const { document } = new JSDOM(html).window;

/** A config path like "/world/dive-1.mp4" is built from world/out/dive-1.mp4. */
// a reference may carry a cache busting version, which is not part of the name
const assetFor = (ref) => path.join(OUT, path.basename(ref.split("?")[0]));

describe("the film the config points at", () => {
  it("has a poster and a clip for every scene", () => {
    expect(world.sections.length).toBeGreaterThanOrEqual(4);

    for (const section of world.sections) {
      expect(existsSync(assetFor(section.still)), section.still).toBe(true);
      expect(existsSync(assetFor(section.clip)), section.clip).toBe(true);
    }
  });

  it("has exactly one wipe between each pair of scenes", () => {
    expect(world.connectors).toHaveLength(world.sections.length - 1);
    for (const connector of world.connectors) {
      expect(existsSync(assetFor(connector)), connector).toBe(true);
    }
  });

  it("keeps every asset inside Cloudflare's 25 MiB per file limit", async () => {
    const limit = 25 * 1024 * 1024;

    for (const section of world.sections) {
      for (const ref of [section.still, section.clip]) {
        const { size } = await stat(assetFor(ref));
        expect(size, `${ref} is ${(size / 1024 / 1024).toFixed(1)} MB`).toBeLessThan(limit);
      }
    }
  });

  it("gives every scene a label and an id, and no duplicates", () => {
    const ids = world.sections.map((section) => section.id);
    expect(new Set(ids).size).toBe(ids.length);

    for (const section of world.sections) {
      expect(section.label.length).toBeGreaterThan(0);
    }
  });

  it("names its scene after each part of the site, in order", () => {
    // one scene per part: the pages, the bar's nav and the film all say the same
    // five words
    expect(world.sections.map((section) => section.label)).toEqual([
      "Presentation",
      "Education",
      "Experience",
      "Projects",
      "Contact",
    ]);
  });

  it("travels vertically: the camera moves in y, and nothing glides sideways", async () => {
    const motion = await read("world/motion.mjs");

    expect(motion).toMatch(/overlay=x=\$\{-CAM\.x0\}:y='-\(/);
    expect(motion).not.toContain("x='-(");
  });

  it("keeps the camera inside the backdrop, or the base shows through", async () => {
    // The backdrop is the only layer covering the whole stage and it travels the
    // slowest, so the window's bottom edge catches it first. Past that, the frame
    // gets a black band along the bottom.
    const { CAM } = await import("../world/motion.mjs");
    const { SPEEDS } = await import("../world/scenes.mjs");

    const backdropDrift = 1 + SPEEDS.back;
    expect(CAM.y0 + CAM.travel * backdropDrift).toBeLessThanOrEqual(CAM.h);
  });

  it("joins the scenes with a vertical wipe", async () => {
    const motion = await read("world/motion.mjs");

    expect(motion).toContain("xfade=transition=wipeup");
    expect(motion).not.toContain("wipeleft");
  });

  it("writes those names into the film itself, not only into the copy beside it", () => {
    return read("world/scenes.mjs").then((scenes) => {
      for (const name of [
        "PRESENTATION",
        "EDUCATION",
        "EPITECH",
        "EXPERIENCE",
        "MIGALABS",
        "PROJECTS",
        "CONTACT",
      ]) {
        expect(scenes, name).toContain(`"${name}"`);
      }
    });
  });
});

describe("the copy, by the landing page rules", () => {
  const sections = world.sections;

  it("titles each scene with the part it belongs to", () => {
    // the name is the title, at the start of the scene, not a label in a corner
    for (const section of sections) {
      expect(section.title, section.id).toBe(section.label);
    }
  });

  it("says one thing per scene: an eyebrow, a title and a line of body", () => {
    for (const section of sections) {
      expect(section.eyebrow.length, section.id).toBeGreaterThan(2);
      expect(section.title.length, section.id).toBeGreaterThan(3);
      expect(section.body.length, section.id).toBeGreaterThan(40);
    }
  });

  it("versions the film, so a cached clip is refetched when the bytes change", () => {
    for (const section of world.sections) {
      expect(section.clip, section.id).toMatch(/\?v=\d+$/);
      expect(section.still, section.id).toMatch(/\?v=\d+$/);
    }

    // the joins are film too: an unversioned one would pair new dives with an
    // old wipe out of the cache
    expect(world.connectors.length).toBeGreaterThan(0);
    for (const connector of world.connectors) {
      expect(connector).toMatch(/\?v=\d+$/);
    }
  });

  it("keeps hyphens out of the sentences", () => {
    for (const section of sections) {
      for (const text of [section.eyebrow, section.title, section.body]) {
        expect(text, `${section.id}: ${text}`).not.toMatch(/\w-\w/);
      }
    }
  });

  it("avoids the usual generated filler", () => {
    const cliches = [
      "elevate",
      "seamless",
      "unleash",
      "next gen",
      "game changer",
      "delve",
      "in the world of",
    ];
    const all = sections
      .flatMap((section) => [section.eyebrow, section.title, section.body])
      .join(" ")
      .toLowerCase();

    for (const cliche of cliches) {
      expect(all, cliche).not.toContain(cliche);
    }
  });

  it("offers exactly one action, and it is a real one", () => {
    const withCta = sections.filter((section) => section.cta);
    const last = sections[sections.length - 1];

    expect(withCta).toHaveLength(1);
    expect(last.cta.primary.href).toMatch(/^https:\/\/mail\.google\.com\/mail\//);
    expect(last.cta.secondary.href).toBe("/services"); // the prices page
    for (const action of Object.values(last.cta)) {
      expect(action.label).not.toMatch(/learn more|submit|click here/i);
    }
  });

  it("paces the first and last scenes slower than the transit", () => {
    expect(sections[0].scroll).toBeGreaterThan(1);
    expect(sections[sections.length - 1].scroll).toBeGreaterThan(1);
  });
});

describe("one gesture, one scene", () => {
  it("turns a wheel notch into the next or previous scene", () => {
    expect(sceneStep({ delta: 120, index: 0, count: 5 })).toBe(1);
    expect(sceneStep({ delta: -120, index: 3, count: 5 })).toBe(2);
  });

  it("answers the arrow and page keys, and the ends", () => {
    for (const key of ["ArrowDown", "PageDown", " "]) {
      expect(sceneStep({ key, index: 1, count: 5 }), key).toBe(2);
    }
    expect(sceneStep({ key: "ArrowUp", index: 2, count: 5 })).toBe(1);
    expect(sceneStep({ key: "Home", index: 4, count: 5 })).toBe(0);
    expect(sceneStep({ key: "End", index: 0, count: 5 })).toBe(4);
  });

  it("stays put at the ends, and leaves other keys alone", () => {
    expect(sceneStep({ delta: 120, index: 4, count: 5 })).toBeNull();
    expect(sceneStep({ delta: -120, index: 0, count: 5 })).toBeNull();
    expect(sceneStep({ delta: 0, index: 2, count: 5 })).toBeNull();
    expect(sceneStep({ key: "Tab", index: 2, count: 5 })).toBeNull();
  });

  it("keeps the whole film short enough that a gesture is a scene", () => {
    // count the real per-section dwell, not just the defaults
    const screens =
      world.sections.reduce((total, section) => total + (section.scroll ?? world.diveScroll), 0) +
      world.connectors.length * world.connScroll;

    expect(world.diveScroll).toBeLessThanOrEqual(0.8);
    expect(world.connScroll).toBeLessThanOrEqual(0.5);
    expect(screens).toBeLessThan(6);
  });
});

describe("the world page", () => {
  it("describes itself", () => {
    expect(document.documentElement.getAttribute("lang")).toBe("en");
    expect(document.title).toBe("Portfolio - Juan Felipe Diaz");
    expect(document.querySelector('meta[name="description"]')?.content.length).toBeGreaterThan(40);
    expect(document.querySelector('meta[property="og:title"]')).toBeTruthy();
    expect(document.querySelector('link[rel="icon"]')).toBeTruthy();
  });

  it("has one heading, and loads the engine before its config", () => {
    // the fallback heading inside <noscript> only counts for visitors without
    // JavaScript, and jsdom parses it into the tree
    const headings = [...document.querySelectorAll("h1")].filter(
      (heading) => !heading.closest("noscript"),
    );

    expect(headings).toHaveLength(1);
    expect(headings[0].textContent).toContain("print shop");

    const scripts = [...document.querySelectorAll("script[src]")].map((script) =>
      script.getAttribute("src"),
    );
    expect(scripts).toEqual(["/world/engine.js", "/world.js"]);
    expect(document.querySelector('script[src="/world.js"]').getAttribute("type")).toBe("module");
  });

  it("still offers a way in without JavaScript", () => {
    const fallback = document.querySelector("noscript");

    expect(fallback.textContent).toContain("five slide version");
    expect(fallback.querySelector('a[href="/home"]')).toBeTruthy();
    expect(fallback.querySelector('a[href^="https://mail.google.com/mail/"]')).toBeTruthy();
  });

  it("keeps the deck reachable from the world", () => {
    expect(world.brand.href).toBe("/home");
  });

  it("keeps the primary button readable on the dark sheet", () => {
    // the engine hardcodes white text, and the button itself is white here
    expect(html).toMatch(/\.sw-btn--primary[\s\S]*?color:\s*var\(--sw-bg\)/);
  });

  it("opens the contact email in a new tab, without handing over the opener", () => {
    const dom = new JSDOM(`
      <div class="sw-copy__cta">
        <a href="https://mail.google.com/mail/?view=cm&amp;fs=1&amp;to=jfdiazbus%40gmail.com">Email me</a>
        <a href="/services">See services</a>
      </div>
    `);

    openExternalActions(dom.window.document, "https://portfolio.example");

    const [email, services] = dom.window.document.querySelectorAll("a");
    expect(email.target).toBe("_blank");
    expect(email.rel).toBe("noopener");
    expect(services.getAttribute("target")).toBeNull();
    expect(services.getAttribute("rel")).toBeNull();
  });
});

describe("the vendored engine", () => {
  it("is the upstream scrub engine, unmodified in shape", async () => {
    const engine = await read("world/engine.js");

    expect(engine).toContain("function mountScrollWorld(container, config)");
    expect(engine).toContain("module.exports = { mountScrollWorld }");
    expect(engine.length).toBeGreaterThan(8000);
  });

  it("feeds the engine the same tokens the site uses, so the world matches", async () => {
    const page = await read("world.html");

    for (const token of ["--sw-bg", "--sw-ink", "--sw-ink-soft", "--sw-accent", "--sw-font-body"]) {
      expect(page, token).toContain(token);
    }

    expect(page).toContain("--sw-bg: var(--bg)");
    expect(page).toContain("--sw-accent: var(--accent)");
    expect(page).toContain("--bg: #0a0a0a");
    expect(page).not.toContain("--paper");
  });
});
